# KNIME new Python Script node%%00010import io%%00010import re%%00010import time%%00010import requests%%00010import pandas as pd%%00010import knime.scripting.io as knio%%00010%%00010# ---------- Inputs ----------%%00010df_in = knio.input_tables[0].to_pandas()%%00010ID_COL = "protein_id"%%00010%%00010ENDPOINT = "https://rest.uniprot.org/uniprotkb/search"%%00010%%00010# Keep below UniProt's OR-condition limit.%%00010# 80 IDs gives 79 OR operators in the primary query.%%00010BATCH_SIZE = int(knio.flow_variables.get("batch_size", 80))%%00010%%00010FIELDS_RAW = knio.flow_variables.get(%%00010 "uniprot_columns",%%00010 "accession,id,protein_name,gene_primary,organism_name,organism_id,reviewed"%%00010)%%00010%%00010# ---------- Field cleanup ----------%%00010fields = []%%00010for f in FIELDS_RAW.split(","):%%00010 f = f.strip()%%00010 if f:%%00010 fields.append(f)%%00010%%00010# accession returns the TSV column "Entry"%%00010fields = ["accession"] + [f for f in fields if f != "accession"]%%00010%%00010# remove duplicate fields while preserving order%%00010seen = set()%%00010fields = [f for f in fields if not (f in seen or seen.add(f))]%%00010FIELDS = ",".join(fields)%%00010%%00010# ---------- Helpers ----------%%00010session = requests.Session()%%00010session.headers.update({%%00010 "User-Agent": "KNIME-UniProt-accession-annotation/1.0"%%00010})%%00010%%00010def clean_acc(x):%%00010 if pd.isna(x):%%00010 return ""%%00010 return str(x).strip().upper()%%00010%%00010def chunks(lst, n):%%00010 for i in range(0, len(lst), n):%%00010 yield lst[i:i+n]%%00010%%00010def request_with_retry(url, params, max_tries=5):%%00010 last_error = None%%00010%%00010 for attempt in range(1, max_tries + 1):%%00010 r = session.get(%%00010 url,%%00010 params=params,%%00010 timeout=120%%00010 )%%00010%%00010 if r.status_code == 200:%%00010 return r%%00010%%00010 last_error = (%%00010 f"HTTP {r.status_code}
"%%00010 f"URL: {r.url}
"%%00010 f"Response head:
{r.text[:1000]}"%%00010 )%%00010%%00010 if r.status_code in (429, 500, 502, 503, 504):%%00010 time.sleep(min(60, 2 ** attempt))%%00010 continue%%00010%%00010 raise RuntimeError(last_error)%%00010%%00010 raise RuntimeError(f"Exceeded retries. Last error:
{last_error}")%%00010%%00010def read_tsv(tsv):%%00010 if not tsv or not tsv.strip():%%00010 return pd.DataFrame()%%00010 return pd.read_csv(io.StringIO(tsv), sep="	", dtype=str)%%00010%%00010def build_primary_query(ids):%%00010 """%%00010 Primary UniProt accession query.%%00010 IMPORTANT: only one field per ID to avoid exceeding UniProt's OR limit.%%00010 """%%00010 return "(" + " OR ".join(f"accession_id:{x}" for x in ids) + ")"%%00010%%00010def build_isoform_query(ids):%%00010 """%%00010 Isoform accessions such as P12345-2 are usually better queried via accession.%%00010 Kept separate to avoid accession_id OR accession duplication.%%00010 """%%00010 return "(" + " OR ".join(f"accession:{x}" for x in ids) + ")"%%00010%%00010def build_secondary_query(x):%%00010 """%%00010 Secondary/replaced accession lookup.%%00010 Done one-by-one because the returned Entry may be the current primary accession,%%00010 not the original queried accession.%%00010 """%%00010 return f"sec_acc:{x}"%%00010%%00010def fetch_uniprot_search(query, fields, size=500):%%00010 params = {%%00010 "query": query,%%00010 "format": "tsv",%%00010 "fields": fields,%%00010 "size": size,%%00010 }%%00010%%00010 r = request_with_retry(ENDPOINT, params)%%00010 return r.text, r.url, r.headers.get("Content-Type", "")%%00010%%00010# ---------- Prepare input ----------%%00010df = df_in.copy()%%00010df["__row_order__"] = range(len(df))%%00010df["__query_acc__"] = df[ID_COL].apply(clean_acc)%%00010%%00010# UniProt accession regex:%%00010# - classic 6-character accessions%%00010# - newer 10-character accessions%%00010# - optional isoform suffix, e.g. P12345-2%%00010acc_regex = re.compile(%%00010 r"^(?:"%%00010 r"[OPQ][0-9][A-Z0-9]{3}[0-9]"%%00010 r"|"%%00010 r"[A-NR-Z][0-9](?:[A-Z][A-Z0-9]{2}[0-9]){1,2}"%%00010 r")(?:-\d+)?$"%%00010)%%00010%%00010valid_mask = df["__query_acc__"].apply(lambda x: bool(acc_regex.match(x)))%%00010df_valid = df[valid_mask].copy()%%00010df_invalid = df[~valid_mask].copy()%%00010%%00010df_invalid_issues = df_invalid[[ID_COL, "__query_acc__"]].copy()%%00010df_invalid_issues["reason"] = "invalid_format"%%00010%%00010ids_valid_unique = list(dict.fromkeys(df_valid["__query_acc__"].tolist()))%%00010%%00010primary_ids = [x for x in ids_valid_unique if "-" not in x]%%00010isoform_ids = [x for x in ids_valid_unique if "-" in x]%%00010%%00010# ---------- Primary accession queries ----------%%00010api_frames = []%%00010debug_rows = []%%00010%%00010for batch in chunks(primary_ids, BATCH_SIZE):%%00010 q = build_primary_query(batch)%%00010%%00010 tsv, url, content_type = fetch_uniprot_search(%%00010 q,%%00010 FIELDS,%%00010 size=500%%00010 )%%00010%%00010 tmp = read_tsv(tsv)%%00010%%00010 debug_rows.append({%%00010 "step": "primary_accession_id",%%00010 "n_submitted": len(batch),%%00010 "query": q[:1000],%%00010 "url": url[:2000],%%00010 "content_type": content_type,%%00010 "response_head": tsv[:500],%%00010 "n_returned": len(tmp),%%00010 })%%00010%%00010 if not tmp.empty:%%00010 if "Entry" not in tmp.columns:%%00010 raise RuntimeError(%%00010 "UniProt response is missing expected 'Entry' column.
"%%00010 f"URL: {url}
"%%00010 f"Content-Type: {content_type}
"%%00010 f"Response head:
{tsv[:1000]}"%%00010 )%%00010%%00010 tmp["__query_acc__"] = tmp["Entry"].astype(str).str.strip().str.upper()%%00010 tmp["__match_type__"] = "primary_accession_id"%%00010 api_frames.append(tmp)%%00010%%00010# ---------- Isoform accession queries ----------%%00010for batch in chunks(isoform_ids, BATCH_SIZE):%%00010 q = build_isoform_query(batch)%%00010%%00010 tsv, url, content_type = fetch_uniprot_search(%%00010 q,%%00010 FIELDS,%%00010 size=500%%00010 )%%00010%%00010 tmp = read_tsv(tsv)%%00010%%00010 debug_rows.append({%%00010 "step": "isoform_accession",%%00010 "n_submitted": len(batch),%%00010 "query": q[:1000],%%00010 "url": url[:2000],%%00010 "content_type": content_type,%%00010 "response_head": tsv[:500],%%00010 "n_returned": len(tmp),%%00010 })%%00010%%00010 if not tmp.empty:%%00010 if "Entry" not in tmp.columns:%%00010 raise RuntimeError(%%00010 "UniProt isoform response is missing expected 'Entry' column.
"%%00010 f"URL: {url}
"%%00010 f"Content-Type: {content_type}
"%%00010 f"Response head:
{tsv[:1000]}"%%00010 )%%00010%%00010 # For isoforms, the returned Entry may be the base accession.%%00010 # For exact isoform-level joining, UniProt ID mapping may still be preferable.%%00010 tmp["__query_acc__"] = tmp["Entry"].astype(str).str.strip().str.upper()%%00010 tmp["__match_type__"] = "isoform_accession"%%00010 api_frames.append(tmp)%%00010%%00010df_api_primary = (%%00010 pd.concat(api_frames, ignore_index=True)%%00010 if api_frames%%00010 else pd.DataFrame(columns=["Entry", "__query_acc__", "__match_type__"])%%00010)%%00010%%00010if not df_api_primary.empty:%%00010 df_api_primary = df_api_primary.drop_duplicates(subset=["__query_acc__"], keep="first")%%00010%%00010primary_found = set(df_api_primary["__query_acc__"].astype(str))%%00010%%00010# ---------- Secondary accession fallback ----------%%00010secondary_frames = []%%00010%%00010secondary_candidates = [%%00010 x for x in primary_ids%%00010 if x not in primary_found%%00010]%%00010%%00010for x in secondary_candidates:%%00010 q = build_secondary_query(x)%%00010%%00010 tsv, url, content_type = fetch_uniprot_search(%%00010 q,%%00010 FIELDS,%%00010 size=10%%00010 )%%00010%%00010 tmp = read_tsv(tsv)%%00010%%00010 debug_rows.append({%%00010 "step": "secondary_sec_acc",%%00010 "n_submitted": 1,%%00010 "query": q,%%00010 "url": url[:2000],%%00010 "content_type": content_type,%%00010 "response_head": tsv[:500],%%00010 "n_returned": len(tmp),%%00010 })%%00010%%00010 if not tmp.empty:%%00010 if "Entry" not in tmp.columns:%%00010 raise RuntimeError(%%00010 "UniProt secondary-accession response is missing expected 'Entry' column.
"%%00010 f"URL: {url}
"%%00010 f"Content-Type: {content_type}
"%%00010 f"Response head:
{tsv[:1000]}"%%00010 )%%00010%%00010 # Important:%%00010 # The returned Entry may be the current primary accession.%%00010 # The join key must remain the original queried secondary accession.%%00010 tmp["__query_acc__"] = x%%00010 tmp["__match_type__"] = "secondary_accession"%%00010 secondary_frames.append(tmp)%%00010%%00010df_api_secondary = (%%00010 pd.concat(secondary_frames, ignore_index=True)%%00010 if secondary_frames%%00010 else pd.DataFrame(columns=["Entry", "__query_acc__", "__match_type__"])%%00010)%%00010%%00010# ---------- Combine API results ----------%%00010df_api = pd.concat(%%00010 [df_api_primary, df_api_secondary],%%00010 ignore_index=True%%00010)%%00010%%00010if not df_api.empty:%%00010 mapping_counts = df_api.groupby("__query_acc__").size().rename("__mapping_count__")%%00010 df_api = df_api.merge(%%00010 mapping_counts,%%00010 how="left",%%00010 left_on="__query_acc__",%%00010 right_index=True%%00010 )%%00010%%00010 df_ambiguous = df_api[df_api["__mapping_count__"] > 1].copy()%%00010%%00010 # Avoid multiplying KNIME rows.%%00010 df_api_join = df_api.drop_duplicates(subset=["__query_acc__"], keep="first").copy()%%00010else:%%00010 df_ambiguous = pd.DataFrame()%%00010 df_api_join = df_api.copy()%%00010%%00010# ---------- Join back to original order ----------%%00010out = (%%00010 df.merge(%%00010 df_api_join,%%00010 how="left",%%00010 on="__query_acc__"%%00010 )%%00010 .sort_values("__row_order__")%%00010 .drop(columns=["__row_order__"])%%00010)%%00010%%00010# Keep __query_acc__, Entry, __match_type__ for debugging.%%00010# Later you can remove helper columns if desired:%%00010# out = out.drop(columns=["__query_acc__"])%%00010%%00010# ---------- Issues ----------%%00010mapped_set = set(df_api_join["__query_acc__"].astype(str)) if not df_api_join.empty else set()%%00010%%00010df_not_found = df_valid[%%00010 ~df_valid["__query_acc__"].isin(mapped_set)%%00010][[ID_COL, "__query_acc__"]].copy()%%00010%%00010df_not_found["reason"] = "not_found"%%00010%%00010if not df_ambiguous.empty:%%00010 cols = ["__query_acc__", "Entry", "__mapping_count__"]%%00010 available_cols = [c for c in cols if c in df_ambiguous.columns]%%00010 df_ambiguous_issues = df_ambiguous[available_cols].copy()%%00010 df_ambiguous_issues[ID_COL] = df_ambiguous_issues["__query_acc__"]%%00010 df_ambiguous_issues["reason"] = "multiple_mappings"%%00010else:%%00010 df_ambiguous_issues = pd.DataFrame(%%00010 columns=[ID_COL, "__query_acc__", "Entry", "__mapping_count__", "reason"]%%00010 )%%00010%%00010issues = pd.concat(%%00010 [%%00010 df_invalid_issues,%%00010 df_not_found,%%00010 df_ambiguous_issues,%%00010 ],%%00010 ignore_index=True,%%00010 sort=False%%00010)%%00010%%00010debug_df = pd.DataFrame(debug_rows)%%00010%%00010# ---------- Outputs ----------%%00010# 0: annotations%%00010knio.output_tables[0] = knio.Table.from_pandas(out)%%00010%%00010# 1: issues%%00010knio.output_tables[1] = knio.Table.from_pandas(issues)%%00010%%00010# 2: debug info%%00010# Add a third output port in KNIME to inspect response URLs and response heads.%%00010try:%%00010 knio.output_tables[2] = knio.Table.from_pandas(debug_df)%%00010except Exception:%%00010 pass
